exercises.solution:
package main

import (
    "fmt"
    "time"
)

func main() {
    now := time.Date(2024, 1, 15, 14, 30, 45, 123456789, time.UTC)
    fmt.Println(now.Format("2006-01-02 15:04:05.000000000-07:00"))
    fmt.Println("Hour:", now.Hour())
    fmt.Println("Minute:", now.Minute())

    after := now.Add(1 * time.Second)
    fmt.Println("After sleep:", after.Format("2006-01-02 15:04:05.000000000-07:00"))
}
